fn reverse(a: &[i32]) -> Vec<i32> {
    // Preallocate a vector of the same length as `a`
    let mut result = Vec::with_capacity(a.len());
    // Push elements from `a` in reverse order
    for &item in a.iter().rev() {
        result.push(item);
    }
    result
}

